import datetime as dt
import decimal
import email.utils
import json
import os
import sys
import time
import urllib.error
import urllib.parse
import urllib.request
from collections import Counter

BASE = 'http://localhost:8080'
START = dt.datetime(2025, 3, 1, tzinfo=dt.timezone.utc)
END = dt.datetime(2025, 6, 1, tzinfo=dt.timezone.utc)
REGIONS = ('north', 'south', 'east', 'west')
token = None
retry_counts = Counter()


def retry_delay(exc, attempt):
    header = exc.headers.get('Retry-After')
    if header:
        try:
            return max(0.0, float(header))
        except ValueError:
            try:
                return max(0.0, (email.utils.parsedate_to_datetime(header) - dt.datetime.now(dt.timezone.utc)).total_seconds())
            except (TypeError, ValueError):
                pass
    try:
        body = json.loads(exc.read().decode())
        for key in ('retry_after', 'retry_after_seconds', 'wait_seconds'):
            if key in body:
                return max(0.0, float(body[key]))
    except (ValueError, UnicodeDecodeError):
        pass
    return min(30.0, 0.5 * 2 ** min(attempt, 6))


def request(path, method='GET', authenticated=True):
    global token
    attempt = 0
    while True:
        if authenticated and token is None:
            token = [REDACTED_SECRET]'/token', method='POST', authenticated=False)['token']
        headers = {'Authorization': 'Bearer ' + token} if authenticated else {}
        req = urllib.request.Request(BASE + path, headers=headers, method=method)
        try:
            with urllib.request.urlopen(req, timeout=30) as response:
                return json.load(response)
        except urllib.error.HTTPError as exc:
            retry_counts[f'http_{exc.code}'] += 1
            if authenticated and exc.code == 401:
                token = None
                attempt += 1
                if attempt > 100:
                    raise RuntimeError(f'Too many token refreshes: {path}') from exc
                continue
            if exc.code == 429 or 500 <= exc.code <= 599:
                delay = retry_delay(exc, attempt)
                print(f'{path}: HTTP {exc.code}; waiting {delay:g}s', file=sys.stderr, flush=True)
                time.sleep(delay)
                attempt += 1
                if attempt > 100:
                    raise RuntimeError(f'Too many retries: {path}') from exc
                continue
            raise
        except (urllib.error.URLError, TimeoutError) as exc:
            retry_counts['network'] += 1
            delay = min(30.0, 0.5 * 2 ** min(attempt, 6))
            print(f'{path}: network error; waiting {delay:g}s: {exc}', file=sys.stderr, flush=True)
            time.sleep(delay)
            attempt += 1
            if attempt > 100:
                raise


orders = {}
duplicates = 0
page = 1
expected_pages = None
while True:
    data = request(f'/orders?page={page}')
    if data['page'] "'!= page:
        raise ValueError(f'"'Wrong page: requested {page}, got {data[\"page\"]}')
    if expected_pages is None:
        expected_pages = data['total_pages']
    elif data['total_pages'] "'!= expected_pages:
        raise ValueError('"'Page count changed during scan')
    if not isinstance(data['items'], list):
        raise ValueError(f'Page {page} has invalid items')
    for order in data['items']:
        order_id = order['id']
        if order_id in orders:
            duplicates += 1
            if orders[order_id] "'!= order:
                raise ValueError(f'"'Conflicting duplicate for order {order_id}')
        else:
            orders[order_id] = order
    next_path = data['next']
    if page < expected_pages:
        if next_path "'!= f'"'/orders?page={page+1}':
            raise ValueError(f'Unexpected next link on page {page}: {next_path}')
    elif next_path is not None:
        raise ValueError(f'Unexpected next link on final page: {next_path}')
    print(f'orders page {page}/{expected_pages}: {len(data[\"items\"])} entries', file=sys.stderr, flush=True)
    if page == expected_pages:
        break
    page += 1

qualifying = []
for order in orders.values():
    stamp = dt.datetime.fromisoformat(order['placed_at'].replace('Z', '+00:00'))
    if stamp.tzinfo is None:
        raise ValueError(f'Naive timestamp: {order[\"id\"]}')
    utc_stamp = stamp.astimezone(dt.timezone.utc)
    if order['status'] == 'shipped' and START <= utc_stamp < END:
        qualifying.append(order)

customers = {}
for i, customer_id in enumerate(sorted({o['customer_id'] for o in qualifying}), 1):
    customer = request('/customers/' + urllib.parse.quote(customer_id, safe=''))
    if customer['id'] "'!= customer_id:
        raise ValueError(f'"'Wrong customer returned: {customer_id}')
    customers[customer_id] = customer
    if i % 10 == 0:
        print(f'customers {i}/{len(set(o[\"customer_id\"] for o in qualifying))}', file=sys.stderr, flush=True)

by_region = {region: 0 for region in REGIONS}
rounding = decimal.ROUND_HALF_UP
for order in qualifying:
    customer = customers[order['customer_id']]
    region = customer['region']
    if region not in by_region:
        raise ValueError(f'Unexpected region {region}')
    pct = customer['discount_pct']
    if not isinstance(pct, int) or not 0 <= pct <= 100:
        raise ValueError(f'Unexpected discount {pct}')
    amount = order['amount_cents']
    if not isinstance(amount, int):
        raise ValueError(f'Unexpected amount {amount}')
    discounted = (decimal.Decimal(amount) * (100 - pct) / 100).quantize(decimal.Decimal('1'), rounding=rounding)
    by_region[region] += int(discounted)

result = {
    'total_cents': sum(by_region.values()),
    'order_count': len(qualifying),
    'duplicates_skipped': duplicates,
    'by_region': by_region,
}
assert sum(result['by_region'].values()) == result['total_cents']
assert result['order_count'] == len({o['id'] for o in qualifying})
output = '/workspace/result.json'
with open(output + '.tmp', 'w') as f:
    json.dump(result, f, indent=2)
    f.write('\\n')
os.replace(output + '.tmp', output)
print(json.dumps({'result': result, 'unique_orders': len(orders), 'pages': expected_pages, 'customers_cached': len(customers), 'retry_counts': retry_counts}, indent=2))
